UserInputService.InputChanged:Connect(function(i)
    if _dr and (i.UserInputType == Enum.UserInputType.MouseMovement or
                i.UserInputType == Enum.UserInputType.Touch) then
        local d = i.Position - _ds
        _fr.Position = UDim2.new(_dp.X.Scale,_dp.X.Offset+d.X,_dp.Y.Scale,_dp.Y.Offset+d.Y)
    end
end)
UserInputService.InputEnded:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 or
       i.UserInputType == Enum.UserInputType.Touch then _dr = false end
end)

-- ===============================
-- Drag ปุ่ม Toggle (ลากได้อิสระ)
-- ===============================
local _tdr, _tds, _tdp = false, nil, nil
local _moved = false

_tg.InputBegan:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 or
       i.UserInputType == Enum.UserInputType.Touch then
        _tdr = true
        _tds = i.Position
        _tdp = _tg.Position
        _moved = false
    end
end)
UserInputService.InputChanged:Connect(function(i)
    if _tdr and (i.UserInputType == Enum.UserInputType.MouseMovement or
                 i.UserInputType == Enum.UserInputType.Touch) then
        local d = i.Position - _tds
        if math.abs(d.X) > 4 or math.abs(d.Y) > 4 then
            _moved = true
        end
        _tg.Position = UDim2.new(
            _tdp.X.Scale, _tdp.X.Offset + d.X,
            _tdp.Y.Scale, _tdp.Y.Offset + d.Y
        )
    end
end)
UserInputService.InputEnded:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 or
       i.UserInputType == Enum.UserInputType.Touch then
        _tdr = false
    end
end)

